CREATE TABLE IF NOT EXISTS workspaces(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,is_public INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS members(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,role TEXT NOT NULL,initials TEXT NOT NULL,color TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(workspace_id INTEGER NOT NULL REFERENCES workspaces(id),member_id INTEGER NOT NULL REFERENCES members(id),role TEXT NOT NULL CHECK(role IN ('owner','editor','viewer')),PRIMARY KEY(workspace_id,member_id));
CREATE TABLE IF NOT EXISTS projects(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,client TEXT NOT NULL,color TEXT NOT NULL,progress INTEGER NOT NULL,due_date TEXT NOT NULL,workspace_id INTEGER NOT NULL DEFAULT 1 REFERENCES workspaces(id));
CREATE TABLE IF NOT EXISTS tasks(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('todo','in_progress','review','done')),priority TEXT NOT NULL CHECK(priority IN ('low','medium','high')),project_id INTEGER NOT NULL REFERENCES projects(id),assignee_id INTEGER REFERENCES members(id),due_date TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at TEXT,changed_by INTEGER REFERENCES members(id),request_key TEXT UNIQUE,request_payload TEXT,create_result TEXT);
CREATE TABLE IF NOT EXISTS activity(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,text TEXT NOT NULL,member_id INTEGER NOT NULL REFERENCES members(id),created_at TEXT NOT NULL,workspace_id INTEGER NOT NULL DEFAULT 1 REFERENCES workspaces(id));
CREATE TABLE IF NOT EXISTS invitations(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,workspace_id INTEGER NOT NULL REFERENCES workspaces(id),token_hash TEXT NOT NULL UNIQUE,role TEXT NOT NULL CHECK(role IN ('editor','viewer')),expires_at TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES members(id),accepted_by INTEGER REFERENCES members(id),email TEXT);
CREATE TABLE IF NOT EXISTS accounts(member_id INTEGER PRIMARY KEY REFERENCES members(id),email TEXT NOT NULL UNIQUE,password_salt TEXT NOT NULL,password_hash TEXT NOT NULL,email_verified INTEGER NOT NULL DEFAULT 1,password_version INTEGER NOT NULL DEFAULT 1,mfa_secret TEXT,mfa_pending TEXT,mfa_pending_until BIGINT,mfa_counter BIGINT NOT NULL DEFAULT -1);
CREATE UNIQUE INDEX IF NOT EXISTS account_email_lower ON accounts(lower(email));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,member_id INTEGER NOT NULL REFERENCES accounts(member_id),expires_at BIGINT NOT NULL CHECK(expires_at>0),session_id TEXT NOT NULL UNIQUE,created_at BIGINT NOT NULL DEFAULT 0,device TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS projects_workspace ON projects(workspace_id);
CREATE INDEX IF NOT EXISTS activity_workspace ON activity(workspace_id,id);
CREATE INDEX IF NOT EXISTS tasks_project_state_due ON tasks(project_id,status,due_date,id);
CREATE INDEX IF NOT EXISTS tasks_project_due ON tasks(project_id,due_date,id);
CREATE TABLE IF NOT EXISTS task_history(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,task_id INTEGER NOT NULL REFERENCES tasks(id),workspace_id INTEGER NOT NULL REFERENCES workspaces(id),member_id INTEGER REFERENCES members(id),action TEXT NOT NULL,before_json TEXT,after_json TEXT NOT NULL,version INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(task_id,version));
CREATE INDEX IF NOT EXISTS task_history_workspace ON task_history(workspace_id,id);

CREATE OR REPLACE FUNCTION flow_task_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.changed_by IS NOT NULL THEN
  PERFORM 1 FROM memberships m JOIN projects p ON p.workspace_id=m.workspace_id WHERE p.id=NEW.project_id AND m.member_id=NEW.changed_by AND m.role IN ('owner','editor') FOR SHARE OF m;
  IF NOT FOUND THEN RAISE EXCEPTION 'flow_access_denied'; END IF;
 END IF;
 IF NEW.assignee_id IS NOT NULL THEN
  PERFORM 1 FROM memberships m JOIN projects p ON p.workspace_id=m.workspace_id WHERE p.id=NEW.project_id AND m.member_id=NEW.assignee_id FOR SHARE OF m;
  IF NOT FOUND THEN RAISE EXCEPTION 'flow_assignee_missing'; END IF;
 END IF;
 RETURN NEW;
END;
$$;
CREATE TRIGGER task_access_guard BEFORE INSERT OR UPDATE ON tasks FOR EACH ROW EXECUTE FUNCTION flow_task_guard();
CREATE OR REPLACE FUNCTION flow_invitation_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 PERFORM 1 FROM memberships WHERE workspace_id=NEW.workspace_id AND member_id=NEW.created_by AND role='owner' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'flow_access_denied'; END IF;
 RETURN NEW;
END;
$$;
CREATE TRIGGER invitation_owner_insert BEFORE INSERT ON invitations FOR EACH ROW EXECUTE FUNCTION flow_invitation_guard();
CREATE OR REPLACE FUNCTION flow_task_history() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE old_json TEXT; action_name TEXT;
BEGIN
 IF NEW.changed_by IS NULL OR (TG_OP='UPDATE' AND NEW.version<=OLD.version) THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN
  old_json:=json_build_object('title',OLD.title,'description',OLD.description,'status',OLD.status,'priority',OLD.priority,'projectId',OLD.project_id,'assigneeId',OLD.assignee_id,'dueDate',OLD.due_date,'deletedAt',OLD.deleted_at)::text;
  action_name:=CASE WHEN OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN 'deleted' WHEN OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL THEN 'restored' ELSE 'updated' END;
 ELSE action_name:='created';
 END IF;
 INSERT INTO task_history(task_id,workspace_id,member_id,action,before_json,after_json,version,created_at) VALUES(NEW.id,(SELECT workspace_id FROM projects WHERE id=NEW.project_id),NEW.changed_by,action_name,old_json,json_build_object('title',NEW.title,'description',NEW.description,'status',NEW.status,'priority',NEW.priority,'projectId',NEW.project_id,'assigneeId',NEW.assignee_id,'dueDate',NEW.due_date,'deletedAt',NEW.deleted_at)::text,NEW.version,to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
 RETURN NEW;
END;
$$;
CREATE TRIGGER task_history_created AFTER INSERT ON tasks FOR EACH ROW EXECUTE FUNCTION flow_task_history();
CREATE TRIGGER task_history_updated AFTER UPDATE OF title,description,status,priority,project_id,assignee_id,due_date,deleted_at ON tasks FOR EACH ROW EXECUTE FUNCTION flow_task_history();
INSERT INTO workspaces(id,name,is_public) VALUES(1,'Общее пространство',1) ON CONFLICT DO NOTHING;
SELECT setval(pg_get_serial_sequence('workspaces','id'),GREATEST(1,(SELECT COALESCE(MAX(id),1) FROM workspaces)));
